begin;
select plan(33);

select has_function('public', 'create_gable_covering_takeoff_draft', 'covering takeoff RPC exists');
select ok(has_function_privilege('tetopro_covering_writer', 'public.create_gable_covering_takeoff_draft(uuid,uuid,uuid,uuid,uuid,text,uuid,uuid)', 'EXECUTE'), 'restricted server writer can call takeoff RPC');
select ok(not has_function_privilege('authenticated', 'public.create_gable_covering_takeoff_draft(uuid,uuid,uuid,uuid,uuid,text,uuid,uuid)', 'EXECUTE'), 'authenticated callers cannot call takeoff writer');
select ok(not has_table_privilege('tetopro_covering_writer', 'public.material_takeoffs', 'INSERT'), 'writer has no direct takeoff table insert grant');
select ok(not has_table_privilege('tetopro_covering_writer', 'public.material_takeoff_items', 'INSERT'), 'writer has no direct takeoff item insert grant');

set local role postgres;
