 ('00000000-0000-4000-8000-000000000623','00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000620','DEMO eltérő hossz','piece',1100,1000,4000,'demo','DEMO eltérő méret');

grant execute on function public.create_gable_covering_takeoff_draft(uuid,uuid,uuid,uuid,uuid,text,uuid,uuid) to postgres;
select is((select draft_created from public.create_gable_covering_takeoff_draft(
 '00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000610','00000000-0000-4000-8000-000000000616','00000000-0000-4000-8000-000000000618','00000000-0000-4000-8000-000000000621','DEMO 20 lemezes tervezet','00000000-0000-4000-8000-000000000624','00000000-0000-4000-8000-000000000001')),true,'historical covering revision creates new draft');
select is((select final_quantity from public.material_takeoff_items where takeoff_id=(select id from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000000624')),20::numeric,'20 sheets remain 20 ordering pieces');
select is((select quantity_unit::text from public.material_takeoff_items where takeoff_id=(select id from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000000624')),'piece','ordering unit is piece');
select is((select estimation_method::text from public.material_takeoff_items where takeoff_id=(select id from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000000624')),'calculated','calculated quantity is not marked manual');
select is((select source_calculation_revision_id from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000000624'),'00000000-0000-4000-8000-000000000618','selected historical calculation revision is retained');
select is((select source_roof_model_revision_id from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000000624'),'00000000-0000-4000-8000-000000000613','exact historical roof revision is retained');
select is((select price_snapshot from public.material_takeoff_items where takeoff_id=(select id from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000000624')),null::jsonb,'no catalog price is fabricated or assigned');
select is((select data_provenance::text from public.material_takeoff_items where takeoff_id=(select id from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000000624')),'user_provided','manual catalog association remains user provided');
select is((select material_snapshot->>'sourceGeometryCalculationRevisionId' from public.material_takeoff_items where takeoff_id=(select id from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000000624')),'00000000-0000-4000-8000-000000000617','exact roof geometry calculation source is snapshotted');
select is((select material_snapshot #>> '{sourceOutputSnapshot,covering,purchasedNominalAreaMm2}' from public.material_takeoff_items where takeoff_id=(select id from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000000624')),'110000000','authoritative source output snapshot is preserved');
select is((select material_snapshot->>'sourceGeometryStaleAtTransfer' from public.material_takeoff_items where takeoff_id=(select id from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000000624')),'true','stale source is disclosed and preserved');
select is((select status::text from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000000624'),'draft','conversion never auto-approves');
select is((select draft_created from public.create_gable_covering_takeoff_draft(
 '00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000610','00000000-0000-4000-8000-000000000616','00000000-0000-4000-8000-000000000618','00000000-0000-4000-8000-000000000621','DEMO 20 lemezes tervezet','00000000-0000-4000-8000-000000000624','00000000-0000-4000-8000-000000000001')),false,'same operation reuses draft');
select is((select count(*)::int from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000000624'),1,'idempotent retry creates one draft');
select throws_ok($$select * from public.create_gable_covering_takeoff_draft('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000610','00000000-0000-4000-8000-000000000616','00000000-0000-4000-8000-000000000618','00000000-0000-4000-8000-000000000621','DEMO megváltozott név','00000000-0000-4000-8000-000000000624','00000000-0000-4000-8000-000000000001')$$,'22023',null,'changed payload under same operation key is rejected');
select throws_ok($$select * from public.create_gable_covering_takeoff_draft('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000610','00000000-0000-4000-8000-000000000616','00000000-0000-4000-8000-000000000618','00000000-0000-4000-8000-000000000622','DEMO rossz egység','00000000-0000-4000-8000-000000000625','00000000-0000-4000-8000-000000000001')$$,'22023',null,'square meter catalog variant is rejected for sheet count');
select throws_ok($$select * from public.create_gable_covering_takeoff_draft('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000610','00000000-0000-4000-8000-000000000616','00000000-0000-4000-8000-000000000618','00000000-0000-4000-8000-000000000623','DEMO rossz hossz','00000000-0000-4000-8000-000000000626','00000000-0000-4000-8000-000000000001')$$,'22023',null,'dimensionally conflicting catalog variant is rejected');
select throws_ok($$select * from public.create_gable_covering_takeoff_draft('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000611','00000000-0000-4000-8000-000000000616','00000000-0000-4000-8000-000000000618','00000000-0000-4000-8000-000000000621','DEMO idegen projekt','00000000-0000-4000-8000-000000000627','00000000-0000-4000-8000-000000000001')$$,'P0002',null,'cross project source is rejected');
select throws_ok($$select * from public.create_gable_covering_takeoff_draft('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000610','00000000-0000-4000-8000-000000000615','00000000-0000-4000-8000-000000000618','00000000-0000-4000-8000-000000000621','DEMO forged source id','00000000-0000-4000-8000-000000000628','00000000-0000-4000-8000-000000000001')$$,'P0002',null,'revision cannot be selected under a different calculation ID');

set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select throws_ok($$select * from public.create_gable_covering_takeoff_draft('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000610','00000000-0000-4000-8000-000000000616','00000000-0000-4000-8000-000000000618','00000000-0000-4000-8000-000000000621','DEMO közvetlen RPC','00000000-0000-4000-8000-000000000629','00000000-0000-4000-8000-000000000001')$$,'42501',null,'authenticated direct writer bypass is denied');
set local role postgres;
select throws_ok($$update public.material_takeoff_items set material_snapshot='{}'::jsonb where takeoff_id=(select id from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000000624')$$,'P0001',null,'transferred source item snapshot is immutable');
update public.material_takeoffs set status='approved',approved_by='00000000-0000-4000-8000-000000000001',approved_at=now() where transfer_request_key='00000000-0000-4000-8000-000000000624';
select is((select status::text from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000000624'),'approved','existing approval lifecycle may explicitly approve the draft');
select is((select draft_created from public.create_gable_covering_takeoff_draft(
 '00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000610','00000000-0000-4000-8000-000000000616','00000000-0000-4000-8000-000000000618','00000000-0000-4000-8000-000000000621','DEMO 20 lemezes tervezet','00000000-0000-4000-8000-000000000624','00000000-0000-4000-8000-000000000001')),false,'retry of approved takeoff reuses without recreating it');
select is((select status::text from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000000624'),'approved','idempotent retry does not change approved status');
select is((select draft_created from public.create_gable_covering_takeoff_draft(
 '00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000610','00000000-0000-4000-8000-000000000616','00000000-0000-4000-8000-000000000618','00000000-0000-4000-8000-000000000621','DEMO második piszkozat','00000000-0000-4000-8000-000000000630','00000000-0000-4000-8000-000000000001')),true,'new conversion creates a separate draft');
select is((select status::text from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000000624'),'approved','new conversion does not overwrite approved takeoff');
select throws_ok($$update public.material_takeoffs set name='DEMO átírás' where transfer_request_key='00000000-0000-4000-8000-000000000624'$$,'P0001',null,'approved takeoff remains immutable');
select is((select count(*)::int from public.material_takeoff_items where takeoff_id=(select id from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000000624')),1,'failed mutations leave one source item');

select * from finish();
rollback;
